from functools import lru_cache

def solve():
    n = int(input())
    k = int(input())
    s = input()

    @lru_cache(maxsize=None)
    def dfs(i, count):
        if count == k:
            return 1
        elif count > k or i >= len(s):
            return 0
        else:
            res = 0
            for c in s[:i]:
                res += dfs(i+1, count + (1 if c == 'B' else 0))
            return res

    operations = []
    for i in range(1, len(s)+1):
        for c in s[:i]:
            if dfs(i, (1 if c == 'B' else 0)) > dfs(i+1, k) and (dfs(i, (1 if c == 'B' else 0) + 1 if i > 1 else True):
                operations.append((i, 'A' if c == 'B' else 'B'))
                k -= 1 if c == 'B' else 0
                break
    print(len(operations))
    for op in operations:
        print(*op)

solve()
```

