import sys
from collections import defaultdict
from functools import reduce
from itertools import accumulate, repeat

def powerset(iterable):
    s = list(iterable)
    return reduce(lambda a, i: a + [a[:i] + a[i:] for i in range(1, len(s) + 1)], s, [[]])

def build_prefix_mask(s):
    n = len(s)
    mask = [0] * (1 << n)
    for i in range(n):
        mask[1 << i] = 1 << i
    for i in range(2, (1 << n)):
        mask[i] = mask[i & (i - 1)] | mask[i ^ (i & (i - 1))]
    return {x: i for i, x in enumerate(accumulate(mask, lambda x, y: x | y))}

def is_substring(x, s):
    m = build_prefix_mask(s)
    return any(m[x[i:]] for i in range(len(x) - len(s) + 1))

def next_string(s):
    return "".join(repeat(s, 2))

def solve():
