    x = sys.stdin.readline().rstrip()
    s = sys.stdin.readline().rstrip()
    pow_set = powerset([x])
    for candidate in pow_set:
        if is_substring(candidate, s):
            return 1
        power = set(build_prefix_mask(candidate))
        for op in range(1, m * n):
            next_candidate = set(build_prefix_mask(next_string(candidate))) & power
            if s in next_candidate:
                return op
    return -1

