import heapq

def dijkstra(n, A):
    m = [i for i in range(n + 1)]
    h = [(i, 1, i) for i in range(1, n + 1)]
    heapq.heapify(h)
    while h:
        (u, c, _) = heapq.heappop(h)
        if m[u] == u:
            for v in range(u + 1, n + 1):
                if A[u] + 1 == m[v]:
                    heapq.heappush(h, (v, c + 1, v))
                m[v] = min(m[v], v)
    return m

def solve(n, k, x):
    if k > n:
        return -1

    m = dijkstra(n + 1, [0] + [float('inf')] + list(range(1, x + 1)))
    d = [0] * (k + 1)
    for i in range(1, n + 1):
        d[m[i]] += 1

    dp = []
    for i in range(1, k + 1):
        if d[i] > 0:
            heapq.heappush(dp, (-i, i))
    ans = -float('inf')
    for i in range(1, k + 1):
        while len(dp) > 0 and dp[0][0] > i:
            back = heapq.heappop(dp)[1]
            ans -= back * (d[back] - 1)
            d[back] -= 1
        if len(dp) == 0 or dp[0][0] != i:
            heapq.heappush(dp, (i, min(x - i, d[i])))
        ans += i * d[i]
    return ans

