import collections
from itertools import product

def from_bits(bits):
    return ''.join(chr(ord('a') + i) for i, b in enumerate(reversed(bits)) if b)

def solve(grid):
    rows, cols = len(grid), len(grid[0])

    cols_with_chars = [[] for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '.':
                cols_with_chars[c].append((r, grid[r][c]))

    def dfs(word, stack):
        if not stack:
            yield word
            return

        r, c = stack[-1]
        stack = stack[:-1]
        for nrm, new_word in dfs(word + cols_with_chars[c][nrm][1], stack + [(r + (1 << nrm), cols_with_chars[c][nrm][0])]):
            if r + (1 << nrm) < rows:
                yield new_word

    def bfs(word, queue):
        if len(queue) > len(word):
            yield word
            return

        r, c, nrm = queue[-1]
        queue = queue[:-1]
        for new_word, new_queue in bfs(word + cols_with_chars[c][nrm][1], queue + [(r + (1 << nrm), cols_with_chars[c][nrm][0])]):
            if r + (1 << nrm) < rows:
                yield new_word

    words = list(dfs('', tuple(reversed(range(rows))) + [(0, 0)]))
    words += list(bfs('', tuple(range(rows))) + [(rows - 1, 0)])
    return '\n'.join(from_bits(bits) for _, bits in sorted(collections.ChainMap(*(enumerate(v for v in zip(*[list(w) for w in zip(*grid)])))), key=lambda x: -x)) if words else 'No solution found.'

