import bisect

def get_prefix_sum(a, n):
    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + a[i]
    return prefix_sum

def get_diff(prefix_sum, n, k):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = prefix_sum[i]
        for j in range(i - 1, 0, -1):
            dp[j] = max(dp[j], dp[i] - dp[i - j])
    def dfs(l, r, start, k):
        if k == 1:
            return dp[r - l + 1]
        half_k = k // 2
        l1, r1 = l, bisect.bisect_right(a, a[l] + half_k)
        l2, r2 = r1, r
        if r1 - l1 + 1 > half_k:
            r1 -= 1
        if dfs(l, r1, start, half_k) + dfs(r1 + 1, r, r1, k - half_k) < dp[r - l + 1]:
            dp[r - l + 1] = dfs(l, r1, start, half_k) + dfs(r1 + 1, r, r1, k - half_k)
            start = r1 + 1
        for i in range(start, r1):
            dp[i] = prefix_sum[r - l + 1] - dp[i] - dp[r1] + dp[i - (r1 - l1 + 1)]
        return dp[r - l + 1]

    return dfs(1, n, 0, k)

