import collections
import re

def longest_non_palindromic_subseq(s):
    d = {}

    def is_palindrome(ss):
        if ss in d:
            return d[ss]
        if len(ss) <= 1:
            d[ss] = True
            return True
        first, last = ss[0], ss[-1]
        for i in range(1, len(ss) - 1, 2):
            if ss[i] != first and ss[i] != last:
                d[ss] = False
                return False
        if re.search(r'^.+\1.*\1$', ss[1:-1]):
            d[ss] = False
        else:
            d[ss] = True
        return d[ss]

    def dfs(pos, sub):
        if pos == len(s):
            return 0 if is_palindrome(sub) else len(sub)
        d[sub] = is_palindrome(sub)
        result = max(dfs(pos+1, sub), dfs(pos + 1, sub+s[pos]))
        return result if d[sub] else max(result, dfs(pos + 1, sub+s[pos]))

    return dfs(0, '')

def main():
    tests = int(input())
    for _ in range(tests):
        s = input()
        print(longest_non_palindromic_subseq(s))

main()

