import functools

@functools.lru_cache(maxsize=None)
def dfs(s, i, parity, memo):
    if i >= len(s):
        return parity == 0
    key = (i, s[i])
    if key in memo:
        return memo[key]

    for j in range(i, -1, -1):
        if s[j] == parity:
            memo[key] = not dfs(s, j, 1 - parity, memo)
            if not memo[key]:
                break
    else:
        memo[key] = True

    return memo[key]

