from collections import namedtuple
import sys

Point = namedtuple("Point", ("x", "y"))

def bfs(maze, start, end):
    queue = [start]
    visited = set()
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    while queue:
        current = queue.pop(0)
        if current == end:
            # If we find the end, return the number of visited nodes minus 1 (the start node is not counted)
            return len(visited) - 1
        visited.add(current)

        for dx, dy in directions:
            neighbor = Point(current.x + dx, current.y + dy)
            if 0 <= neighbor.x < len(maze) and 0 <= neighbor.y < len(maze[0]) and maze[neighbor.x][neighbor.y] and neighbor not in visited:
                queue.append(neighbor)

    # If no path is found, return infinity
    return float("inf")

def main():
    T = int(input().strip())

    for _ in range(T):
        n, m = map(int, input().strip().split())
        maze = [[1] * m for _ in range(n)]
        start, end = map(Point, input().strip().split())

        obstacles = bfs(maze, start, end)

        if obstacles == float("inf"):
            print(-1)
        else:
            # Place obstacles on the visited cells
            for i in range(n):
                for j in range(m):
                    if not maze[i][j] and (i, j) not in visited:
                        maze[i][j] = 0
                        obstacles += 1
