import itertools
import math

def solve(n, s, r):
    if n == 2:
        return sorted(list(itertools.combinations([1,2,3,4,5,6], 2)))[r][0], sorted(list(itertools.combinations([1,2,3,4,5,6], 2)))[r][1]

