    for i in range(1, 7):
        diff = s - i
        if diff in dp:
            continue
        if r < i:
            continue
        if diff <= i:
            dp[diff] = (i,)
            max_diff = min(max_diff, diff)
        else:
            sub_res = solve(n - 1, diff, r - i)
            if sub_res:
                dp[diff] = (i,) + sub_res
                max_diff = min(max_diff, diff)
    for i in range(6, 0, -1):
        if max_diff + i <= r or max_diff + i > s:
            continue
        if max_diff + i in dp:
            res = dp[max_diff + i][1:] + (i,)
            res.sort()
            return res
    assert False, "No solution found"

