```python
from itertools import accumulate
from collections import deque

def is_palindrome(s: str, left: int, right: int) -> bool:
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def find_longest_palindrome(s: str) -> tuple[int, int, int]:
    n = len(s)
    dp = [None] * n
    max_len = -1
    max_left = -1
    max_right = -1
    for i in range(n):
        for j in range(i, n):
            if is_palindrome(s, i, j):
                if j - i + 1 > max_len:
                    max_len = j - i + 1
                    max_left = i
                    max_right = j
        dp[i] = max_len

    # Check for palindromes of odd length
    odd_len_sum = sum(dp) - dp[0]
    odd_len_left = 0
    for i in range(1, n):
        if dp[i] == 1:
            odd_len_sum -= 1
            odds = deque([i])
        elif dp[i] > 1:
            prev_j = i - dp[i]
            if dp[prev_j] == 1:
                odds.append(prev_j)
        if len(odds) == 3:
            left, mid, right = odds.popleft(), odds.popleft(), i
            if s[left] == s[right] and is_palindrome(s, left + 1, mid - 1):
                return left, mid, right

    return max_left, max_left + max_len, max_right

def solve(s: str):
    n = len(s)
    if n % 2 == 0:
        if accumulate(map(int, s), lambda x, y: x + y) % 2 == 0:
            return "Yes"
        return "No"

    left, mid, right = find_longest_palindrome(s)
    if left == mid == right and accumulate(map(int, s[(left + 1):mid]), lambda x, y: x + y) % 2 == 0:
        return "Yes"
    if left != mid:
        if accumulate(map(int, s[left:mid]), lambda x, y: x + y) % 2 == 0 and accumulate(map(int, s[mid + 1:right + 1]), lambda x, y: x + y) % 2 == 0:
            return "Yes"
    return "No"
