from collections import deque

def is_palindrome(s):
    return s == s[::-1]

def is_possible(s):
    n = len(s)

    def dfs(l, r):
        # Base case: one element segment
        if l == r:
            return True
        # Recursive case: check if the center element is a palindrome itself
        # and check left and right segments for palindrome property
        if is_palindrome(s[l:r+1]):
            return True
        for k in range(l, r + 1):
