def find(x):
    if parents[x] != x:
        parents[x] = find(parents[x])
    return parents[x]

def union(x, y):
    root_x = find(x)
    root_y = find(y)
    if root_x == root_y:
        return False
    parents[root_y] = root_x
    sizes[root_x] += sizes[root_y]
    return True

def is_ugly(arr):
    size = len(arr)
    parents, sizes = [i for i in range(size)], [1] * size
    for i in range(1, size):
        if union(i-1, arr[i] - arr[:i]):
            return True
    return False

def topological_sort(arr):
    size = len(arr)
    in_degree = [0] * size
    adj_list = [[] for _ in range(size)]

    for i in range(1, size):
        for j in range(i):
            if arr[i] < arr[j] + arr[:i]:
                in_degree[arr[j] - arr[:i]] += 1
                adj_list[arr[j] - arr[:i]].append(i)

    queue = [i for i, d in enumerate(in_degree) if d == 0]
    topsort = []
    visited = set()

    while queue:
        u = queue.pop()
        topsort.append(arr[u])
        visited.add(u)

        for v in adj_list[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return topsort

