        if i == len(q) - 1:
            if q[i] == 0:
                q.pop()
                if all(q):
                    print("YES")
                    return
                q.extendleft(q.popleft())
                backtrack(i - 1)
                q.extend(q.popleft())
            return

        for j in range(i + 1, min(i + k, len(q))):
            if q[i] == q[j]:
                operations.append((i, j))

        for leng in range(k, i, -1):
            for j in range(i, min(i + leng, len(q))):
                if (j - i) % leng == 0:
                    q[i:j + 1] = list(reversed(sorted(q[i:j + 1])))
                    if all(q[i:j + 1]) or backtrack(j):
