from collections import defaultdict

def prime_factorization(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def solve():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        cheeses = []
        for _ in range(n):
            a, b = list(map(int, input().strip().split()))
            factors = prime_factorization(a) + prime_factorization(b)
            g = sum(factors)
            cheeses.append((g, a, b))
        cheeses.sort()
        edges = [(gcd(a, b), a, b) for a, b in (zip(cheeses, cheeses[1:]) if gcd(cheeses[0][1], cheeses[1][1]) == 1)]
        edges += [(0, 1, cheeses[0][1])]
        heapq.heapify(edges)
        uf = UnionFind(n)
        ans = 0
        while edges:
            cost, x, y = heapq.heappop(edges)
            rx, ry = uf.find(x), uf.find(y)
            if rx != ry:
                uf.union(rx, ry)
                ans += 2 * (cost + max(x, y))
        print(ans)

def UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return
        if self.size[xr] < self.size[yr]:
            xr, yr = yr, xr
        self.parent[yr] = xr
        self.size[xr] += self.size[yr]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if __name__ == '__main__':
    solve()
