    factors = {}
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            cnt = 0
            while n % i:
                n //= i
                cnt += 1
            factors[i] = cnt
            i = 2

    if n > 1:
        factors[n] = 1
    return factors

def solve(a):
    max_val = 0
    factor_map = {}
    for i, val in enumerate(a):
        factors = factorize(val)
        for fac, count in factors.items():
            new_val = factor_map.get(fac, 0) or 0
            new_val += count
            factor_map[fac] = new_val
            product = fac ** new_val
            potential_pairs = list(filter(lambda x: x[0] * x[1] == product, [(a[j], factor_map.get(a[j], 0)) for j in range(i + 1, len(a))]))
            if potential_pairs:
                max_val = max(max_val, gcd(val, product) + sum(val + p[1] for p in potential_pairs))

    return 2022 * sum(a) - max_val

