import sys
from collections import defaultdict, deque
from fractions import gcd

def gcd_extended(a, b):
    if a == 0:
        return (0, 1, b)
    else:
        g, y, x = gcd_extended(b % a, a)
        return (g, x - (b // a) * y, y)

def buryat_game(n, m):
    board = [[-1] * m for _ in range(n)]
    board[0][0] = 0  # chip's starting position

    dy, dx = deque([(0, 1), (1, 0)]), deque([(2, 0), (0, 2)])
    for _ in range(n + m - 2):
        g = gcd(n, m)
        n //= g
        m //= g
        if not m and not n:
            return 'Tonya'
        if not n:
            dy.append((-1 * m, 0))
            m = 0
            continue
        if not m:
            dx.append((0, -1 * n))
            n = 0

        if dy:
            dy_step, dy.popleft() = dy_step + dy[0], gcd_extended(*dy[0])
            if -board[n][m] >= dy_step and board[(n + dy_step) % n][m] == -1:
                board[n + dy_step % n][m] = 0
                continue

        if dx:
            dx_step, dx.popleft() = dx_step + dx[0], gcd_extended(*dx[0])
            if -board[n][m] >= dx_step and board[n][m + dx_step] == -1:
                board[n][m + dx_step] = 0
                continue

    if not dy and not dx:
        return 'Tie'
    return 'Burenka' if board[0][m - 1] == -1 else 'Tonya'

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, m = map(int, sys.stdin.readline().split())
        print(buryat_game(n, m))

if __name__ == "__main__":
    main()
