from collections import defaultdict

def compute(a):
    # Initialize a adjacency list with a defaultdict
    adj = defaultdict(list)
    n = len(a)

    for i in range(n):
        for j in range(n):
            if a[i][j]:
                if i > 0 and a[i - 1][j]: adj[i].append((i - 1, j))
                if i + 1 < n and a[i + 1][j]: adj[i].append((i + 1, j))
                if j > 0 and a[i][j - 1]: adj[i].append((i, j - 1))
                if j + 1 < n and a[i][j + 1]: adj[i].append((i, j + 1))

    # BFS to find the strongly connected components (SCCs)
    scc_ids, scc_idx, scc_count = 0, {}, 0
    def dfs(i, j):
        if (i, j) in scc_idx: return
        scc_idx[(i, j)] = scc_ids
        for next_i, next_j in adj[i][j]:
            dfs(next_i, next_j)
        scc_ids += 1
    for i in range(n):
        for j in range(n):
            if a[i][j] and (i, j) not in scc_idx:
                dfs(i, j)
                scc_count += 1

    # Compute the required number of moves for each SCC
    moves = 0
    for scc in scc_ids:
        if scc in scc_idx: continue
        components = set()
        for i, j in adj[scc]:
            if (i, j) in scc_idx:
                components.add(scc_idx[(i, j)])
        if len(components) == 1:
            moves += 1
        else:
            for c in components:
                moves += scc_count - scc_count[c] - 1
            moves += 1

    return moves

def solve():
    for _ in range(int(input())):
        a = [list(map(int, input().split())) for _ in range(2)]
        print(compute(a))

solve()
```

